], '文化・宗教', '左遷先の永州での作品をまとめた「永州八記」などが知られる。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 819, 'person', null), (467, 768, 'year', null, '韓愈', '中唐の文人・思想家で、古文復興運動を主導し、儒学復興を唱えた。', ARRAY['china'], '文化・宗教', '「原道」「師説」などで仏教批判と道徳的儒教を主張した。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 824, 'person', null), (468, 1017, 'year', null, '周敦頤', '北宋の儒学者で、『太極図説』により宋学の源流とされる。', ARRAY['china'], '文化・宗教', '理気論的宇宙論と道徳論を展開し、後の朱子学に影響を与えた。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1073, 'person', null), (469, 1130, 'year', null, '朱熹', '南宋の儒学者で、朱子学を大成した。理気二元論を唱え、四書集注を著した。', ARRAY['china'], '文化・宗教', '「性即理」「存天理滅人欲」などの命題を通じて東アジアの思想・政治に大きな影響を与えた。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1200, 'person', null), (470, 1472, 'year', null, '王陽明', '明代の儒学者・武人で、心即理・知行合一を唱える陽明学を大成した。', ARRAY['china'], '文化・宗教', '良知の学として日本や朝鮮、近代の東アジア思想にも影響を与えた。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1529, 'person', null), (471, 1019, 'year', null, '司馬光', '北宋の政治家・歴史家で、編年体通史『資治通鑑』を編纂した。', ARRAY['china'], '文化・宗教', '為政者の鑑とすることを目的に歴代王朝の政治史を整理した。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1086, 'person', null), (472, 1113, 'year', null, '王重陽', '金代の道教家で、全真教の開祖とされる。', ARRAY['china'], '文化・宗教', '全真教は後に元代以降の道教に大きな影響を与えた。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1170, 'person', null), (473, 1082, 'year', null, '徽宗', '北宋の皇帝で、書画にも優れた芸術家皇帝として知られる。', ARRAY['china'], '文化・宗教', '院体画を保護し、自らも花鳥画などを制作した。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1135, 'person', null), (474, 701, 'year', null, '李白', '盛唐の詩人で、豪放磊落な詩風から「詩仙」と称された。', ARRAY['china'], '文化・宗教', '杜甫と並んで唐詩を代表し、多くの詩が後世まで愛誦された。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 762, 'person', null), (475, 712, 'year', null, '杜甫', '盛唐から唐代中期にかけて活躍した詩人で、現実を描いた「詩聖」と称される。', ARRAY['china'], '文化・宗教', '安史の乱期の体験を通じて民衆の苦難をうたった作品が多い。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 770, 'person', null), (476, 772, 'year', null, '白居易', '中唐の詩人で、平易な言葉で社会批判や恋愛をうたった。', ARRAY['china'], '文化・宗教', '「長恨歌」「琵琶行」などは日本の平安文学にも影響を与えた。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 846, 'person', null), (477, 303, 'year', null, '王羲之', '東晋の書家で、「書聖」と称される。', ARRAY['china'], '文化・宗教', '蘭亭での詩会を記した「蘭亭序」は行書の名品として名高い。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 361, 'person', null), (478, 709, 'year', null, '顔真卿', '唐代の書家・政治家で、力強い楷書で知られる。', ARRAY['china'], '文化・宗教', '安史の乱で戦死した姪を悼む「祭姪文稿」は忠義と感情のこもった書として名高い。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 785, 'person', null), (479, 32, 'year', null, '班固', '後漢の歴史家で、『漢書』を編纂した。', ARRAY['china'], '文化・宗教', '前漢一代の紀伝体正史として後代の史書編纂の模範となった。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 92, 'person', null), (480, 1037, 'year', null, '蘇軾', '北宋の文人・官僚で、詩文・書画に優れた。', ARRAY['china'], '文化・宗教', '「赤壁賦」などの散文や詞で宋代文学の最高峰の一人とされる。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1101, 'person', null), (481, 1084, 'circa', null, '李清照', '北宋末から南宋初の女性詞人で、繊細な感情表現で知られる。', ARRAY['china'], '文化・宗教', '戦乱や亡夫への思いをうたった詞が高く評価される。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1155, 'person', null), (482, 1230, 'circa', null, '関漢卿', '元代の雑劇作家で、元曲の代表的作家の一人。', ARRAY['china'], '文化・宗教', '「竇娥冤」などの作品で知られ、元曲文学の発展に寄与した。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1300, 'person', null), (483, 1715, 'circa', null, '曹雪芹', '清代の小説家で、『紅楼夢』の作者とされる。', ARRAY['china'], '文化・宗教', '貴族社会の没落と人間関係を描いた長編白話小説で、中国小説史の頂点とされる。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1763, 'person', null), (484, 1500, 'circa', null, '呉承恩', '明代の小説家で、『西遊記』の作者とされる。', ARRAY['china'], '文化・宗教', '三蔵法師の取経物語に基づく白話小説で、四大名著の一つ。', null, '2026-04-11 10:46:16.520475+00', '2026-04-11 10:46:16.520475+00', 1582, 'person', null)